72	  public MultistageGroupByExecutor(int[] groupKeyIds, AggregationFunction[] aggFunctions, int[] filterArgIds,
73	      int maxFilterArgId, AggType aggType, boolean leafReturnFinalResult, DataSchema resultSchema,
74	      Map<String, String> opChainMetadata, @Nullable PlanNode.NodeHint nodeHint) {
75	    _groupKeyIds = groupKeyIds;
76	    _aggFunctions = aggFunctions;
77	    _filterArgIds = filterArgIds;
78	    _maxFilterArgId = maxFilterArgId;
79	    _aggType = aggType;
80	    _leafReturnFinalResult = leafReturnFinalResult;
81	    _resultSchema = resultSchema;
82	    int maxInitialResultHolderCapacity = getMaxInitialResultHolderCapacity(opChainMetadata, nodeHint);
83	    _numGroupsLimit = getNumGroupsLimit(opChainMetadata, nodeHint);
84	
85	    // By default, we compute all groups for SQL compliant results. However, we allow overriding this behavior via
86	    // query option for improved performance.
87	    _filteredAggregationsSkipEmptyGroups = QueryOptionsUtils.isFilteredAggregationsSkipEmptyGroups(opChainMetadata);
88	
89	    int numFunctions = aggFunctions.length;
90	    if (!aggType.isInputIntermediateFormat()) {
91	      _aggregateResultHolders = new GroupByResultHolder[numFunctions];
92	      for (int i = 0; i < numFunctions; i++) {
93	        _aggregateResultHolders[i] =
94	            _aggFunctions[i].createGroupByResultHolder(maxInitialResultHolderCapacity, _numGroupsLimit);
95	      }
96	      _mergeResultHolder = null;
97	    } else {
98	      _mergeResultHolder = new ArrayList<>(maxInitialResultHolderCapacity);
99	      _aggregateResultHolders = null;
100	    }
101	
102	    _groupIdGenerator =
103	        GroupIdGeneratorFactory.getGroupIdGenerator(_resultSchema.getStoredColumnDataTypes(), groupKeyIds.length,
104	            _numGroupsLimit);
105	  }
