108	    if (nodeHint != null) {
109	      Map<String, String> aggregateOptions = nodeHint.getHintOptions().get(PinotHintOptions.AGGREGATE_HINT_OPTIONS);
110	      if (aggregateOptions != null) {
111	        String numGroupsLimitStr = aggregateOptions.get(PinotHintOptions.AggregateOptions.NUM_GROUPS_LIMIT);
112	        if (numGroupsLimitStr != null) {
113	          return Integer.parseInt(numGroupsLimitStr);
114	        }
115	      }
116	    }
117	    Integer numGroupsLimit = QueryOptionsUtils.getNumGroupsLimit(opChainMetadata);
118	    return numGroupsLimit != null ? numGroupsLimit : InstancePlanMakerImplV2.DEFAULT_NUM_GROUPS_LIMIT;
119	  }
